import { operation, resource } from "@tinker/core";
import type { DatabaseConnection, TransactionSettings } from "kysely";

import { database, transaction } from "~/components/database-sqlite/index.server";
import { requestHeaders } from "~/components/requests/index.server";
import { createAccountStream, publishAccountNotice } from "~/components/sync-sqlite/index.server";

import { betterAuthModule, betterAuthStart, kyselyModule, nodeSqliteDialect } from "./modules";
import { authSettings } from "./settings.server";

/** The Postgres `session` trigger has no trigger here: each committed change says so itself. */
const publishSessionChange = operation({
  label: "auth.sessionChange",
  depends: { transaction },
  run: async ({ transaction }) => {
    await transaction.notify("start_sync", "session");
  },
});

/**
 * Better Auth's driver over the app's write connection, with its one checkout waiting for the
 * process's write turn. `node:sqlite` is synchronous and a session transaction stays open
 * across awaits, so a free-running writer would land inside another call's transaction.
 */
const authDriver = resource({
  label: "auth.driver",
  depends: { database, dialect: nodeSqliteDialect },
  factory: async ({ database, dialect }) => {
    const driver = new dialect.NodeSqliteDialect({ database: database.client }).createDriver();
    const turns = new Map<DatabaseConnection, () => void>();

    return {
      async init() {
        await driver.init();
      },
      async destroy() {
        // The database resource owns the connection and closes it with the scope.
      },
      async acquireConnection() {
        const release = await database.writeTurn();

        try {
          const connection = await driver.acquireConnection();

          turns.set(connection, release);

          return connection;
        } catch (error) {
          release();

          throw error;
        }
      },
      async releaseConnection(connection: DatabaseConnection) {
        try {
          await driver.releaseConnection(connection);
        } finally {
          turns.get(connection)?.();
          turns.delete(connection);
        }
      },
      async beginTransaction(connection: DatabaseConnection, settings: TransactionSettings) {
        await driver.beginTransaction(connection, settings);
      },
      async commitTransaction(connection: DatabaseConnection) {
        await driver.commitTransaction(connection);
      },
      async rollbackTransaction(connection: DatabaseConnection) {
        await driver.rollbackTransaction(connection);
      },
    };
  },
});

/**
 * A session delete sends the account notice after its commit: sign-out, a revoked or deleted
 * session, and a deleted user (its sessions go through the same delete) all end here.
 * The SQLite set has no mail component, so sign-in is the only email-password flow: no reset
 * mail and no verification mail.
 */
export const auth = resource({
  label: "auth",
  depends: {
    database,
    settings: authSettings,
    writer: authDriver,
    dialect: nodeSqliteDialect,
    kysely: kyselyModule,
    created: createAccountStream,
    deleted: publishAccountNotice,
    changed: publishSessionChange,
    auth: betterAuthModule,
    start: betterAuthStart,
  },
  factory: async (
    { database, settings, writer, dialect, kysely, created, deleted, changed, auth, start },
    { closing, log },
  ) => {
    const { Kysely } = kysely;
    const base = new dialect.NodeSqliteDialect({ database: database.client });

    const db = new Kysely({
      dialect: {
        createDriver: () => writer,
        createAdapter: () => base.createAdapter(),
        createQueryCompiler: () => base.createQueryCompiler(),
        createIntrospector: (instance) => base.createIntrospector(instance),
      },
    });

    const { betterAuth } = auth;
    const { tanstackStartCookies } = start;

    return betterAuth({
      baseURL: settings.origin,
      secret: settings.secret,
      database: { db, type: "sqlite" },
      session: { deferSessionRefresh: true },
      databaseHooks: {
        user: {
          create: {
            after: async ({ id }) => {
              try {
                await created.run({ input: { accountId: id }, signal: closing });
              } catch (error) {
                log.error("auth.accountStreamFailed", { accountId: id, error: String(error) });
              }
            },
          },
        },
        session: {
          create: {
            after: async ({ userId }) => {
              await created.run({ input: { accountId: userId }, signal: closing });
              await changed.run({ signal: closing });
            },
          },
          update: {
            after: () => changed.run({ signal: closing }),
          },
          delete: {
            after: async ({ userId }) => {
              // The Postgres trigger spoke before the account notice; keep that order.
              await changed.run({ signal: closing });
              await deleted.run({ rawInput: { accountId: userId }, signal: closing });
            },
          },
        },
      },
      emailAndPassword: {
        enabled: true,
      },
      plugins: [tanstackStartCookies()],
    });
  },
});

export const principal = resource({
  label: "request.principal",
  target: "session",
  depends: { auth, headers: requestHeaders },
  factory: async ({ auth, headers }) =>
    (
      await auth.api.getSession({
        headers,
        query: { disableCookieCache: true, disableRefresh: true },
      })
    )?.user ?? null,
});

/** A long stream rechecks the live cookie without using caches or refreshing the session. */
export const liveAccount = operation({
  label: "sync.liveAccount",
  depends: { auth, headers: requestHeaders },
  run: async ({ auth, headers }) =>
    (
      await auth.api.getSession({
        headers,
        query: { disableCookieCache: true, disableRefresh: true },
      })
    )?.user.id ?? null,
});

import { operation } from "@tinker/core";
import { z } from "zod";

import { auth } from "./auth.server";

/**
 * ADR 0103's named protocol exception: the app's auth library owns its HTTP contract, so this
 * operation hands it the whole request and returns its reply as is.
 */
export const handleAuth = operation({
  label: "handleAuth",
  input: z.instanceof(Request),
  depends: { auth },
  run: ({ auth }, { input }) => auth.handler(input),
});

export { auth, principal, liveAccount } from "./auth.server";
export { handleAuth } from "./handle.server";
export { authSettings, authStartup } from "./settings.server";
export { openSync, eventStream } from "./stream.server";

import { resource } from "@tinker/core";

export const betterAuthModule = resource({
  label: "module:better-auth",
  target: "scope",
  factory: () => import("better-auth"),
});

export const betterAuthStart = resource({
  label: "module:better-auth/tanstack-start",
  target: "scope",
  factory: () => import("better-auth/tanstack-start"),
});

/** Better Auth's Kysely adapter owns the SQL over `node:sqlite`, so Kysely is a dep. */
export const kyselyModule = resource({
  label: "module:kysely",
  target: "scope",
  factory: () => import("kysely"),
});

export const nodeSqliteDialect = resource({
  label: "module:@better-auth/kysely-adapter/node-sqlite-dialect",
  target: "scope",
  factory: () => import("@better-auth/kysely-adapter/node-sqlite-dialect"),
});

import { extension, tag } from "@tinker/core";
import { z } from "zod";

export const authSettings = tag({
  label: "auth.settings",
  parse: z.object({ origin: z.url({ protocol: /^https?$/ }), secret: z.string().min(32) }),
});

/** Check the required auth config before serving. */
export const authStartup = extension({
  label: "auth",
  hooks: {
    async start(event) {
      event.resolve(authSettings);

      await event.next();
    },
  },
});

import { operation, resource } from "@tinker/core";
import type { Operation } from "@tinker/core";

import { database } from "~/components/database-sqlite/index.server";
import { raise } from "~/components/errors";
import { backendStop, requestStop, startRequests } from "~/components/requests";
import { notifications, streamCursor, streamRequest } from "~/components/sync-sqlite/index.server";
import type { Sync, Stream } from "~/components/sync-sqlite/index.server";

import { liveAccount } from "./auth.server";
import readFrameRows from "./queries/read_frame.sql";

/** One replay page owns its database read and encoded bytes. */
const readFrame = operation({
  label: "sync.frame",
  depends: { database },
  run: async ({ database }, { input }: Operation.Ctx<Stream.Cursor>): Promise<Stream.Frame> => {
    const next = { public: input.public, private: input.private ? { ...input.private } : null };
    const own = next.private ?? { accountId: "", revision: 0 };

    // One read on the read connection; an empty account name matches no stream.
    const rows = readFrameRows.runSync(database.reader, {
      public: next.public,
      account: own.accountId,
      after: own.revision,
    });

    const events: Sync.Event[] = [];

    for (const row of rows) {
      events.push({
        stream: row.stream,
        revision: row.revision,
        executionId: row.execution_id,
        payload: JSON.parse(row.payload) as Sync.Payload,
      });

      if (row.stream === "public") next.public = row.revision;
      else if (next.private) next.private.revision = row.revision;
    }

    const encoder = new TextEncoder();
    return {
      cursor: next,
      count: events.length,
      bytes: events.length
        ? encoder.encode(
            `event: changes\nid: ${JSON.stringify(next)}\ndata: ${JSON.stringify({ kind: "changes", events })}\n\n`,
          )
        : new Uint8Array(),
    };
  },
});

/** The request owns one subscription, identity lease, and shared account recheck. */
const streamLease = resource({
  label: "sync.streamLease",
  target: "session",
  depends: { notifications, account: liveAccount.controller, backendStop, requestStop },
  factory: async (
    { notifications, account, backendStop, requestStop },
    { signal: cleanup, defer, clock },
  ) => {
    const stop = new AbortController();
    const signal = AbortSignal.any([stop.signal, backendStop, requestStop, cleanup]);
    const done = Symbol("sync.waitDone");
    let subscription: Awaited<ReturnType<typeof notifications.subscribe>> | undefined;
    let expectedAccount: string | null = null;
    let deadline = Infinity;
    let changed = false;
    let checking: Promise<number> | undefined;

    defer(() => lease.close());

    const lease = {
      signal,
      get changed() {
        return changed;
      },
      async open(initial: Stream.Cursor) {
        expectedAccount = initial.private?.accountId ?? null;
        subscription = await notifications.subscribe(stop.abort.bind(stop, done), expectedAccount);
        if (signal.aborted) {
          notifications.close(subscription);
          raise("Cancelled", {});
        }

        const current = await account.run();
        if (initial.private && initial.private.accountId !== current) raise("StreamDenied", {});
        deadline = clock.currentTimeMillis() + 30_000;
        if (current !== expectedAccount) subscription.stale = true;
      },
      async check(): Promise<number> {
        if (!subscription) raise("StreamDisconnected", {});
        if (notifications.ended(subscription) || clock.currentTimeMillis() >= deadline) {
          lease.close();
          return notifications.revision();
        }

        if (checking) return checking;
        if (!subscription.stale) return notifications.revision();
        subscription.stale = false;
        checking = account
          .run()
          .then((current) => {
            if (!signal.aborted && current !== expectedAccount) {
              changed = true;
              stop.abort(done);
            }
            return notifications.revision();
          })
          .finally(() => {
            checking = undefined;
          });
        return checking;
      },
      async wait(after: number) {
        await lease.check();
        if (signal.aborted) return false;
        if (!subscription) raise("StreamDisconnected", {});

        const heartbeat = await notifications.wait(subscription, after, deadline);
        await lease.check();
        return heartbeat;
      },
      revision() {
        return notifications.revision();
      },
      close() {
        if (subscription) notifications.close(subscription);
        stop.abort(done);
      },
    };
    return lease;
  },
});

type Read =
  | { kind: "ended" }
  | { kind: "idle"; wake: number }
  | { kind: "frame"; bytes: Uint8Array };

/** One request advances its cursor; cached frame values are never changed or handed to the body. */
const streamReader = resource({
  label: "sync.streamReader",
  target: "session",
  depends: { lease: streamLease, notifications, requests: startRequests },
  factory: async ({ lease, notifications, requests }) => {
    const frame = requests.scope.controller(readFrame);
    let cursor: Stream.Cursor = { public: 0, private: null };
    let afterWake = -1;
    return {
      async open(initial: Stream.Cursor) {
        await lease.open(initial);
        cursor = { ...initial, private: initial.private ? { ...initial.private } : null };
      },
      async read(): Promise<Read> {
        const wake = await lease.check();
        if (lease.signal.aborted) return { kind: "ended" };
        if (wake === afterWake) return { kind: "idle", wake };
        const privateKey = cursor.private
          ? `${cursor.private.accountId.length}:${cursor.private.accountId}:${cursor.private.revision}`
          : "-";
        const next = await notifications.share(
          `${cursor.public}:${privateKey}`,
          frame.settle.bind(frame),
          cursor,
        );
        await lease.check();
        if (lease.signal.aborted) return { kind: "ended" };

        if (!next.count) {
          afterWake = wake;
          return { kind: "idle", wake };
        }
        if (next.count < 100) afterWake = wake;
        cursor = next.cursor;
        return { kind: "frame", bytes: next.bytes.slice() };
      },
    };
  },
});

/** The request owns pulls and its independent watch loop, even when the client stops reading. */
export const eventStream = resource({
  label: "sync.stream",
  target: "session",
  depends: { lease: streamLease, reader: streamReader },
  factory: async ({ lease, reader }, { defer }) => {
    const encoder = new TextEncoder();
    const accountChange = encoder.encode('event: account\ndata: {"kind":"account-change"}\n\n');
    let output: ReadableStreamDefaultController<Uint8Array> | undefined;
    let ended = false;
    let watching: Promise<void> | undefined;
    let activity = Promise.withResolvers<boolean>();

    const close = () => {
      if (ended) return;
      ended = true;
      activity.resolve(false);

      if (lease.changed) output?.enqueue(accountChange.slice());
      output?.close();
      lease.close();
    };

    lease.signal.addEventListener("abort", close, { once: true });
    defer(async () => {
      close();
      lease.signal.removeEventListener("abort", close);
      await watching;
    });

    return {
      async open(initial: Stream.Cursor) {
        await reader.open(initial);
        let greeted = false;
        return new ReadableStream<Uint8Array>(
          {
            start(controller) {
              output = controller;
              if (ended) {
                controller.close();
                return;
              }
              watching = Promise.resolve()
                .then(async () => {
                  while (!ended) {
                    const wake = await lease.check();
                    if (ended) return;
                    const heartbeat = await lease.wait(wake);

                    const waiting = activity;
                    activity = Promise.withResolvers<boolean>();
                    waiting.resolve(heartbeat);
                  }
                })
                .catch((error) => {
                  if (lease.signal.aborted) {
                    close();
                    return;
                  }
                  ended = true;
                  activity.resolve(false);
                  output?.error(error);
                  lease.close();
                });
            },
            pull(controller) {
              return Promise.resolve()
                .then(async () => {
                  while (!ended) {
                    const awake = activity.promise;
                    const frame = await reader.read();
                    if (frame.kind === "ended") return;
                    if (frame.kind === "frame") {
                      controller.enqueue(frame.bytes);
                      return;
                    }
                    if (lease.revision() !== frame.wake) continue;
                    if (!greeted) {
                      greeted = true;
                      controller.enqueue(encoder.encode(": connected\n\n"));
                      return;
                    }

                    const heartbeat = await awake;
                    await lease.check();
                    if (!heartbeat) continue;
                    if (!ended) controller.enqueue(encoder.encode(": heartbeat\n\n"));
                    return;
                  }
                })
                .catch((error) => {
                  if (lease.signal.aborted) {
                    close();
                    return;
                  }
                  ended = true;
                  activity.resolve(false);
                  output?.error(error);
                  lease.close();
                });
            },
            cancel() {
              output = undefined;
              close();
            },
          },
          { highWaterMark: 0 },
        );
      },
    };
  },
});

/** A reconnect cursor wins over the query cursor; both are checked before opening the body. */
export const openSync = operation({
  label: "sync.open",
  input: (raw: unknown) => {
    const request = streamRequest.parse(raw);
    const supplied = request.lastEventId || new URLSearchParams(request.search).get("cursor");
    return {
      cursor: streamCursor.parse(supplied ? JSON.parse(supplied) : { public: 0, private: null }),
    };
  },
  depends: { stream: eventStream },
  run: async ({ stream }, { input }) => stream.open(input.cursor),
});
